import{c as t,Q as a,j as o,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"可執行計劃書：cc-workspace 採用 Sub-Agent + Agent-Team Orchestration","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-03-subagent-agent-team-execution-plan.md","filePath":"research/reports/archive/2026-06-03-subagent-agent-team-execution-plan.md","lastUpdated":1780844007000}'),d={name:"research/reports/archive/2026-06-03-subagent-agent-team-execution-plan.md"};function i(n,e,c,l,s,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="可執行計劃書-cc-workspace-採用-sub-agent-agent-team-orchestration" tabindex="-1">可執行計劃書：cc-workspace 採用 Sub-Agent + Agent-Team Orchestration <a class="header-anchor" href="#可執行計劃書-cc-workspace-採用-sub-agent-agent-team-orchestration" aria-label="Permalink to &quot;可執行計劃書：cc-workspace 採用 Sub-Agent + Agent-Team Orchestration&quot;">​</a></h1><blockquote><p><strong>日期</strong>：2026-06-03 ｜ <strong>語言</strong>：繁體中文（技術術語保留英文） <strong>類型</strong>：execution-plan（配套研究報告 <code>2026-06-03-subagent-agent-team-deep-research.md</code>） <strong>產出方式</strong>：<code>autoresearch:reason</code> 對抗論證（generate → critique → synthesize），含實際 grep 接地驗證 <strong>核心結論</strong>：本 workspace 已有生產級 hub-and-spoke + consensus 實現（<code>gap-vote</code>/<code>autoresearch:predict</code>），<strong>此計劃主要是「盤點 + 文件化 + 補真缺口」，非新建 orchestrator</strong>。 <strong>硬設計規則</strong>：零新增 auto-load rule（byte 餘裕僅 ~1.1K）；所有落地走 <code>.claude/refs/</code> / 既有 skill / GOTCHAS（on-demand）；每階段驗收含 byte 不增斷言。</p></blockquote><hr><h2 id="_0-定位-為何此計劃「主要是盤點-非新建」" tabindex="-1">0. 定位：為何此計劃「主要是盤點，非新建」 <a class="header-anchor" href="#_0-定位-為何此計劃「主要是盤點-非新建」" aria-label="Permalink to &quot;0. 定位：為何此計劃「主要是盤點，非新建」&quot;">​</a></h2><p>四源研究指向的「可靠生產拓撲」——hub-and-spoke + stateless workers + artifact contract + consensus——<strong>本 workspace 已有實現</strong>：</p><table tabindex="0"><thead><tr><th>研究術語</th><th>既有實現</th></tr></thead><tbody><tr><td>hub-and-spoke（orchestrator-worker）</td><td><code>subagent-strategy.md</code>：parent↔child、child 不互通</td></tr><tr><td>stateless worker + artifact contract</td><td><code>gap-vote</code>：vote-matrix + evidence audit schema</td></tr><tr><td>multi-agent debate</td><td><code>autoresearch:predict</code>：3–8 persona + blind judge</td></tr><tr><td>consensus / voting</td><td><code>gap-vote</code>：2/3 deterministic</td></tr><tr><td>task verification（防幻覺自報）</td><td>R4 + dynamic-workflow「機械 grep 重驗」</td></tr><tr><td>echo-chamber 防護</td><td>blind judge + external signal</td></tr></tbody></table><p>因此本計劃<strong>不重寫 <code>subagent-strategy.md</code>、不 day-one 建 nested loop</strong>，而是：(a) 把既成最佳實踐固化為可稽核 canonical、(b) 補兩個有實據的真 fix、(c) 把 MAST 失敗模式對映既有防護並補缺口。</p><hr><h2 id="_1-目標與非目標" tabindex="-1">1. 目標與非目標 <a class="header-anchor" href="#_1-目標與非目標" aria-label="Permalink to &quot;1. 目標與非目標&quot;">​</a></h2><p><strong>目標</strong></p><ol><li>把分散的 sub-agent 最佳實踐固化為單一 canonical 來源（least-privilege、模型路由），消除 silent drift。</li><li>把既有 <code>gap-vote</code>/<code>autoresearch:predict</code> 的 agent-team 能力<strong>顯式對映</strong>到研究拓撲術語，讓未來任務正確選用而非重造。</li><li>把 MAST 14 失敗模式對映既有防護，找真實缺口並最小補強。</li></ol><p><strong>非目標（明確排除）</strong></p><ul><li>不重寫 <code>subagent-strategy.md</code> 核心（fan-out 4 / parent↔child / no self-retry 保留）。</li><li>Day-one 不建 nested multi-agent loop（child 派 child）。</li><li>不新增任何 auto-load rule（byte 預算不允許）。</li><li>不引入 open mesh / 自由 agent-to-agent 通訊。</li><li>不讓 LLM 自由「選隊」（見 §2.2 R5 守則）。</li></ul><hr><h2 id="_2-三階段路線圖" tabindex="-1">2. 三階段路線圖 <a class="header-anchor" href="#_2-三階段路線圖" aria-label="Permalink to &quot;2. 三階段路線圖&quot;">​</a></h2><h3 id="階段一-鞏固現有-sub-agent-實踐-least-privilege-模型路由" tabindex="-1">階段一：鞏固現有 sub-agent 實踐（least-privilege + 模型路由） <a class="header-anchor" href="#階段一-鞏固現有-sub-agent-實踐-least-privilege-模型路由" aria-label="Permalink to &quot;階段一：鞏固現有 sub-agent 實踐（least-privilege + 模型路由）&quot;">​</a></h3><p>落地：1 真 fix（skill frontmatter）+ 1 ref。<strong>零 auto-load 增量。</strong></p><p><strong>行動 1.1 — review-hub least-privilege 修正（VoltAgent 借鏡）</strong></p><ul><li>檔案：<code>.claude/skills/review-hub/SKILL.md</code> frontmatter <code>allowed-tools</code></li><li>改動：移除 <code>Write</code>（reviewer 應 read-only），約 1 行。 <ul><li>接地驗證（reviewer agent 已 grep）：<code>iac-review</code>/<code>ship-review</code>/<code>security-compliance</code> 已是 read-only，僅 <code>review-hub</code> 含 <code>Write</code>。</li></ul></li><li>前置確認：grep review-hub body 是否真有寫檔流程；若有 → 改判 <code>defer</code> 並在 GOTCHAS 記錄豁免，不強拆。</li><li>驗收：<code>grep -L &quot;allowed-tools:.*Write&quot; .claude/skills/{review-hub,ship-review,iac-review,security-compliance}/SKILL.md | wc -l</code> → 預期 <code>4</code>。</li><li>風險：review-hub 實需寫報告 → 誤拆破功能。回滾：<code>git revert</code>（單行）。</li></ul><p><strong>行動 1.2 — 模型路由 canonical 化（wshobson 三層借鏡）</strong></p><ul><li>接地驗證（reviewer agent 已 grep）：路由分散 16 agent frontmatter + autoresearch 路由表 + 3 pilot skills + CLAUDE.md 矩陣 = 多來源 drift 風險。</li><li>落地：新增 <code>.claude/refs/model-routing.md</code>（≤60 行），列 task-type→model 確定性對映為 single source of truth；各 frontmatter 維持但標註「依 model-routing.md」。<strong>不動 auto-load</strong>。</li><li>驗收：<code>test -f .claude/refs/model-routing.md &amp;&amp; grep -c &quot;haiku\\|sonnet\\|opus&quot; .claude/refs/model-routing.md</code> → ≥3。</li><li>風險：與既有 frontmatter <code>model:</code> 矛盾（R7）→ ref 記 <code>TODO(conflict)</code>。回滾：<code>rm</code>。</li></ul><p><strong>階段一 byte gate</strong>：<code>wc -c CLAUDE.md .claude/rules/*.md | tail -1</code> 對基線無增；<code>bash scripts/healthcheck.sh | tail -3</code> FAIL=0。</p><hr><h3 id="階段二-agent-team-模式文件化盤點-接地-gap-vote-debate" tabindex="-1">階段二：agent-team 模式文件化盤點（接地 gap-vote / debate） <a class="header-anchor" href="#階段二-agent-team-模式文件化盤點-接地-gap-vote-debate" aria-label="Permalink to &quot;階段二：agent-team 模式文件化盤點（接地 gap-vote / debate）&quot;">​</a></h3><p>落地：1 ref（拓撲對映表）。<strong>零新建 orchestrator、零 auto-load 增量。</strong></p><p><strong>行動 2.1 — 拓撲術語對映 ref</strong></p><ul><li>落地：<code>.claude/refs/agent-team-patterns.md</code>（≤80 行），把研究術語對映既有設施（見 §0 表），每行附「何時用 / 何時不用」+ token 倍數警語（multi-agent 15×）。</li><li>驗收：<code>test -f .claude/refs/agent-team-patterns.md &amp;&amp; grep -c &quot;gap-vote\\|autoresearch:predict\\|hub-and-spoke&quot; .claude/refs/agent-team-patterns.md</code> → ≥3。</li><li>風險：與既有 skill 重複（違 R2）→ 限定「術語橋接 + 選用指引」，用 <code>→ See</code> 引用不複製 schema。回滾：<code>rm</code>。</li></ul><p><strong>行動 2.2 — 動態 team 組成（確定性 mapping，非 LLM 選隊）</strong></p><ul><li>落地：在 2.1 ref 內加 task-type→team-size 確定性表（接地 AgentVerse「最優 team size」+ Anthropic 量表 1/2-4/10+）：簡單→1、中→2-4、研究廣度→hub+N worker。</li><li><strong>R5 守則明文</strong>：team 組成是 routing（確定性 mapping），由 task-type 查表決定，<strong>不由 LLM 自由選</strong>；LLM 只產 verdict/內容。</li><li>驗收：<code>grep -c &quot;1 \\|2-4\\|10+\\|task-type&quot; .claude/refs/agent-team-patterns.md</code> → 量表存在。</li><li>風險：被誤用為「讓 agent 自選隊」→ ref 內粗體禁令。回滾：<code>rm</code>。</li></ul><p><strong>階段二 byte gate</strong>：同階段一；healthcheck FAIL=0。</p><hr><h3 id="階段三-multi-agent-失敗防護-mast-對映-task-verification" tabindex="-1">階段三：multi-agent 失敗防護（MAST 對映 + task verification） <a class="header-anchor" href="#階段三-multi-agent-失敗防護-mast-對映-task-verification" aria-label="Permalink to &quot;階段三：multi-agent 失敗防護（MAST 對映 + task verification）&quot;">​</a></h3><p>落地：1 ref（MAST 對映矩陣）+ GOTCHAS 補強。<strong>零 auto-load 增量。</strong></p><p><strong>行動 3.1 — MAST 14 失敗模式對映矩陣</strong></p><ul><li>落地：<code>.claude/refs/mast-failure-mapping.md</code>（≤90 行）：14 模式 × <code>{是否已防護 / 防護機制 / 缺口}</code>。</li><li>預期已防護：specification 品質（<code>autoresearch</code> Setup Gate）、agent 幻覺自報完成（<code>gap-vote</code> evidence audit + dynamic-workflow grep 重驗）、echo chamber（blind judge + external signal）。</li><li>驗收：<code>grep -c &quot;^| &quot; .claude/refs/mast-failure-mapping.md</code> → ≥14（14 模式全列）。</li><li>風險：把「已有防護」誤標缺口而過度補（違 R2）→ 每格引用既有機制檔案路徑為證。回滾：<code>rm</code>。</li></ul><p><strong>行動 3.2 — task verification 強化（最大瓶頸，補真缺口）</strong></p><ul><li>條件：僅補 3.1 矩陣標出的<strong>真缺口</strong>，不預先補。最可能缺口：一般 sub-agent 委派未強制 parent 抽驗（<code>gap-vote</code> 已強制 evidence audit，但泛化委派未強制）。</li><li>落地：在 <code>harness-meta</code> GOTCHAS.md 補一條「sub-agent verdict 採信前 parent 必機械 grep 抽驗」（dynamic-workflow 規則泛化），約 3 行。</li><li>驗收：<code>grep -c &quot;parent.*grep\\|抽驗&quot; .claude/skills/harness-meta/GOTCHAS.md</code> → ≥1 新增。</li><li>風險：與既有條目重複 → 先 grep 確認不重複再寫。回滾：<code>git revert</code>。</li></ul><p><strong>階段三 byte gate</strong>：同前；healthcheck FAIL=0。</p><hr><h2 id="_3-風險矩陣" tabindex="-1">3. 風險矩陣 <a class="header-anchor" href="#_3-風險矩陣" aria-label="Permalink to &quot;3. 風險矩陣&quot;">​</a></h2><table tabindex="0"><thead><tr><th>風險</th><th>觸發條件</th><th>緩解（機械）</th><th>回滾</th></tr></thead><tbody><tr><td>token 成本爆炸</td><td>誤用 multi-agent（15×）做單 agent 可解任務</td><td>ref「何時不用」+ 委派量表閘門；<code>autoresearch</code> token budget 表</td><td>不啟動 team；單對話處理</td></tr><tr><td>auto-load byte 超 18,000</td><td>任一行動誤改 <code>.claude/rules/*</code></td><td>每階段 <code>wc -c ... | tail -1</code> 斷言不增；落 refs/skills/GOTCHAS</td><td><code>git revert</code> 該 rule 改動</td></tr><tr><td>coordination overhead</td><td>team-size 過大</td><td>2.2 task-type→size 確定性表</td><td>縮回 1-2 agent</td></tr><tr><td>echo chamber</td><td>debate 只 LLM 自評</td><td>復用既有 blind judge + external signal</td><td>加 guard command</td></tr></tbody></table><hr><h2 id="_4-明確的「不做什麼」及原因" tabindex="-1">4. 明確的「不做什麼」及原因 <a class="header-anchor" href="#_4-明確的「不做什麼」及原因" aria-label="Permalink to &quot;4. 明確的「不做什麼」及原因&quot;">​</a></h2><ul><li><strong>不建 open mesh / agent-to-agent 直接通訊</strong> — 社群共識已淘汰；違 parent↔child。</li><li><strong>Day-one 不建 nested loop</strong> — 非目標；dynamic workflow runtime 已控管 ≤16/≤1000。</li><li><strong>不新增 auto-load rule</strong> — byte 餘裕 ~1.1K，價值可由 on-demand ref 承載。</li><li><strong>不讓 LLM 自由選隊</strong> — 違 R5；組成是 routing（確定性 mapping）。</li><li><strong>不重寫 echo-chamber / consensus 機制</strong> — 既有 blind judge + 2/3 deterministic + evidence audit 已覆蓋。</li><li><strong>child 不 self-retry</strong> — 既有規則保留。</li></ul><hr><h2 id="_5-對抗論證修正記錄-generate-→-critique-→-synthesize" tabindex="-1">5. 對抗論證修正記錄（generate → critique → synthesize） <a class="header-anchor" href="#_5-對抗論證修正記錄-generate-→-critique-→-synthesize" aria-label="Permalink to &quot;5. 對抗論證修正記錄（generate → critique → synthesize）&quot;">​</a></h2><p>實際砍掉/改寫的內容（非空話）：</p><ol><li><strong>違 R4 → 已修</strong>：初稿行動 1.1 驗收原寫「review 類改為 least-privilege」（主觀）→ 改為 <code>grep -L ... | wc -l → 4</code>。所有驗收統一改 bash 命令 + 期望輸出。</li><li><strong>違 byte 上限 → 結構性消解</strong>：初稿曾考慮寫進 <code>subagent-strategy.md</code>（auto-load）→ 全改落 <code>.claude/refs/</code>（on-demand），「零 auto-load 增量 + 每階段 byte 斷言」升為硬規則。</li><li><strong>違 R2（over-engineering）→ 砍 day-one 項</strong>：初稿階段二含「新建 team-orchestrator skill」+「nested loop」→ 發現 <code>gap-vote</code>+<code>autoresearch:predict</code> 已生產級，新建 = 重造。砍除，重定義為「文件化盤點 + 確定性 team-size 表」。</li><li><strong>違 R5 → 新增明文守則</strong>：「動態組成」措辭模糊可能被讀成「agent 自選隊」→ 新增 §2.2 R5 守則 + 列入「不做什麼」。</li><li><strong>echo chamber 不重造</strong>：初稿曾規劃「為 debate 加 judge」→ 確認 <code>autoresearch</code> 已有 blind judge + external signal，改引用不重寫。</li></ol><hr><h2 id="_6-採用順序與接地檔案" tabindex="-1">6. 採用順序與接地檔案 <a class="header-anchor" href="#_6-採用順序與接地檔案" aria-label="Permalink to &quot;6. 採用順序與接地檔案&quot;">​</a></h2><p>建議順序：階段一 → 二 → 三（各階段獨立可驗、可回滾）。每階段為一個原子 commit（R3 commit 顆粒度）。</p><table tabindex="0"><thead><tr><th>動作</th><th>檔案</th><th>階段</th></tr></thead><tbody><tr><td>改</td><td><code>.claude/skills/review-hub/SKILL.md</code></td><td>1.1</td></tr><tr><td>新增</td><td><code>.claude/refs/model-routing.md</code></td><td>1.2</td></tr><tr><td>新增</td><td><code>.claude/refs/agent-team-patterns.md</code></td><td>2.1 + 2.2</td></tr><tr><td>新增</td><td><code>.claude/refs/mast-failure-mapping.md</code></td><td>3.1</td></tr><tr><td>改</td><td><code>.claude/skills/harness-meta/GOTCHAS.md</code></td><td>3.2</td></tr><tr><td><strong>不動</strong></td><td><code>.claude/rules/subagent-strategy.md</code>（核心保留）</td><td>—</td></tr></tbody></table><blockquote><p>本計劃為「採用藍圖」，非本 session 立即執行的改動。實際採用時各行動項依 Harness Loop（OBSERVE→IDENTIFY→PROPOSE→TEST→APPLY→RECORD）逐項驗證，破壞性 APPLY 前 gate 使用者。</p></blockquote>',53)])])}const p=t(d,[["render",i]]);export{h as __pageData,p as default};
